<template><div v-if="event" class="demo-widget tts-widget" :style="widgetStyle(widget.settings)"><div v-if="widget.settings.showAvatar" class="avatar">🔊</div><div><span v-if="widget.settings.showStatus" class="widget-kicker">{{ event.payload?.status || (runtimeMode === 'browser-source' ? 'READY' : 'SIMULATED · READY') }}</span><b v-if="widget.settings.showSpeaker">{{ event.actor?.displayName }}</b><p>{{ event.payload?.text }}</p></div></div></template>
<script setup>import { watch } from 'vue'; import { widgetStyle,useWidgetEvents } from '../../widgetHelpers.js'; const props=defineProps({widget:{type:Object,required:true},runtimeMode:{type:String,default:'editor-preview'},runtimeConfig:{type:Object,default:null}}); const event=useWidgetEvents(props.widget,props.runtimeMode==='browser-source'?null:{actor:{displayName:'VoiceTester'},payload:{text:'Visual preview only — speech playback is not connected.',status:'SIMULATED'}}); watch(event,(next)=>{const config=props.runtimeConfig?.tts||{},text=String(next?.payload?.text||'').trim().slice(0,Number(config.maxLength||200));if(props.runtimeMode!=='browser-source'||config.enabled===false||!text||!('speechSynthesis' in window))return;const utterance=new SpeechSynthesisUtterance(text);utterance.rate=Number(config.rate||1);utterance.pitch=Number(config.pitch??1);utterance.volume=Number(config.volume??1);const voice=window.speechSynthesis.getVoices().find(item=>item.name===config.voice);if(voice)utterance.voice=voice;window.speechSynthesis.cancel();window.speechSynthesis.speak(utterance)})</script>
